import { loadFont } from "@remotion/google-fonts/Outfit";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// Growth Publicidade (agência, cliente MATHEU AGENCIA): motion vertical 1080×1920, 30 fps, 42,5 s, roteiro do cliente em
// cinco cenas: 1 a vitrine que ninguém vê, 2 o mercado (comunicar, se posicionar, ser lembrado), 3 a marca + ideias em
// estratégias + os seis serviços, 4 o diferencial (o gráfico cresce), 5 assinatura: a vitrine acende e o botão de contato.
// Paleta do cliente: marrom café, bege areia, off-white, caramelo e marrom profundo. Outfit nos textos (geométrica como o
// logo). Texto entra com impulso e fica parado; o que se move é a câmera e as ilustrações.
// Cada palavra entra no instante em que é dita (segundos da locução src/voz-v1.mp3, que entra em 0,3 s). Sem áudio
// aqui: trilha e efeitos em tools/make_audio_growth.py, mixagem à parte.

const { fontFamily: FONT } = loadFont("normal", { weights: ["400", "500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const GR_FPS = 30;
export const GR_FRAMES = Math.round(42.5 * GR_FPS);
const VO = 0.3;
const CAFE = "#4B2817";
const AREIA = "#E9D9C2";
const OFF = "#F7F2E9";
const CARAMELO = "#8A6A52";
const DEEP = "#2B211B";
const asset = (f: string) => staticFile(`growth/${f}`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.out(Easing.back(1.6));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const v = (s: number) => s + VO; // segundo da locução → segundo do vídeo
const bump = (t: number, at: number, amt = 0.06, d = 0.4) => (t >= at ? amt * (1 - k(t, at, d)) : 0);

// câmera: [segundo em que chega, escala, x, y do ponto que vai para o centro, duração]. Entre um ponto e outro ela
// continua avançando devagar, então a imagem nunca fica parada.
type Key = [number, number, number, number, number?];
const cam = (t: number, keys: Key[], cy: number) => {
  let [, s, x, y] = keys[0];
  let last = keys[0][0];
  for (let i = 1; i < keys.length; i++) {
    const [at, s1, x1, y1, d = 0.5] = keys[i];
    const p = interpolate(t, [at - d, at], [0, 1], { ...cl, easing: IN_OUT });
    s += (s1 - s) * p;
    x += (x1 - x) * p;
    y += (y1 - y) * p;
    if (t >= at) last = at;
  }
  s *= 1 + 0.045 * Math.min(1, (t - last) / 2.5);
  return `translate(${(540 - x * s).toFixed(1)}px, ${(cy - y * s).toFixed(1)}px) scale(${s.toFixed(4)})`;
};
const World: React.FC<{ t: number; keys: Key[]; cy?: number; children: React.ReactNode }> = ({ t, keys, cy = 1120, children }) => (
  <AbsoluteFill style={{ transform: cam(t, keys, cy), transformOrigin: "0 0" }}>{children}</AbsoluteFill>
);
// faixa da cor do fundo atrás do título, para o que a câmera aproxima não passar por cima do texto
const Shade: React.FC<{ color: string; h?: number }> = ({ color, h = 640 }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: h, background: `linear-gradient(180deg, ${color} 0%, ${color} 78%, ${color}00 100%)`, zIndex: 4 }} />
);

// ───────── texto ─────────
type W = [string, number, boolean?]; // [palavra, segundo da locução, destaque?]
// palavras em destaque seguidas ficam numa caixa só (cantos arredondados, folga igual em volta), que cresce enquanto
// elas são ditas; o texto dentro fica no centro da caixa
const Say: React.FC<{ t: number; words: W[]; size: number; color?: string; pill?: string; ink?: string; weight?: number }> = ({ t, words, size, color = OFF, pill = AREIA, ink = CAFE, weight = 700 }) => {
  const groups: { em: boolean; ws: W[] }[] = [];
  for (const w of words) {
    const last = groups[groups.length - 1];
    if (last && w[2] && last.em) last.ws.push(w);
    else groups.push({ em: !!w[2], ws: [w] });
  }
  const word = (w: string, at: number, i: number) => {
    const e = k(t, v(at) - 0.05, 0.34);
    return (
      <span key={i} style={{ position: "relative", display: "inline-block", opacity: k(t, v(at) - 0.05, 0.12), transform: `translateY(${((1 - e) * size * 0.45).toFixed(1)}px) scale(${(0.72 + 0.28 * pop(t, v(at) - 0.05, 0.42)).toFixed(3)})` }}>{w}</span>
    );
  };
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: `${size * 0.24}px`, whiteSpace: "nowrap", fontFamily: FONT, fontWeight: weight, fontSize: size, lineHeight: 1.16, letterSpacing: "-0.03em", color }}>
      {groups.map((g, gi) => {
        if (!g.em) return <React.Fragment key={gi}>{g.ws.map(([w, at], i) => word(w, at, i))}</React.Fragment>;
        const a0 = v(g.ws[0][1]) - 0.06;
        const a1 = v(g.ws[g.ws.length - 1][1]) + 0.2;
        const grow = g.ws.length > 1 ? 0.35 + 0.65 * io(t, a0 + 0.1, Math.max(0.25, a1 - a0 - 0.1)) : 1;
        return (
          <span key={gi} style={{ position: "relative", display: "inline-flex", alignItems: "center", gap: `${size * 0.22}px`, padding: `${size * 0.1}px ${size * 0.3}px ${size * 0.14}px`, margin: `${size * 0.1}px 0 ${size * 0.04}px`, color: ink, opacity: k(t, a0, 0.12) }}>
            <span style={{ position: "absolute", inset: 0, borderRadius: size * 0.26, background: pill, transform: `scaleX(${(k(t, a0, 0.32) * grow).toFixed(4)})`, transformOrigin: "0 50%" }} />
            {g.ws.map(([w, at], i) => word(w, at, i))}
          </span>
        );
      })}
    </div>
  );
};
const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, gap = 2, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap, zIndex: 5, ...style }}>{children}</div>
);
// frase que ocupa um lugar fixo: só aparece entre `from` e `to`, e some inteira antes da próxima entrar
const Slot: React.FC<{ t: number; from: number; to?: number; top: number; children: React.ReactNode; gap?: number }> = ({ t, from, to, top, children, gap }) => {
  if (t < from - 0.1 || (to !== undefined && t > to)) return null;
  const out = to === undefined ? 0 : io(t, to - 0.2, 0.18);
  return (
    <Col top={top} gap={gap} style={{ opacity: 1 - out, transform: `translateY(${(-out * 24).toFixed(1)}px)` }}>
      {children}
    </Col>
  );
};

// ───────── marca ─────────
// o logo oficial recortado em PNG transparente: a palavra sobe de baixo, letra a letra (máscara que corre da esquerda)
const Logo: React.FC<{ t: number; at: number; w: number; color: "off" | "cafe" | "areia"; subAt?: number }> = ({ t, at, w, color, subAt }) => {
  const rise = k(t, at, 0.7);
  const wipe = io(t, at, 0.6);
  const sub = subAt === undefined ? 0 : k(t, subAt, 0.6);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
      <div style={{ width: w, height: (w * 373) / 1579, overflow: "hidden", clipPath: `inset(0 ${((1 - wipe) * 100).toFixed(2)}% 0 0)` }}>
        <Img src={asset(`logo-word-${color}.png`)} style={{ width: w, transform: `translateY(${((1 - rise) * w * 0.24).toFixed(1)}px)` }} />
      </div>
      {subAt !== undefined ? (
        <div style={{ marginTop: w * 0.05, opacity: sub, transform: `scaleX(${(0.86 + 0.14 * sub).toFixed(4)})` }}>
          <Img src={asset(`logo-sub-${color}.png`)} style={{ width: w, display: "block" }} />
        </div>
      ) : null}
    </div>
  );
};

// ───────── ícones (traço, viewBox 100) ─────────
const SV: React.FC<{ s: number; children: React.ReactNode; c?: string; sw?: number }> = ({ s, children, c = AREIA, sw = 6 }) => (
  <svg width={s} height={s} viewBox="0 0 100 100" fill="none" stroke={c} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round" style={{ overflow: "visible" }}>
    {children}
  </svg>
);
const Heart: React.FC<{ x: number; y: number; s: number; fill: string }> = ({ x, y, s, fill }) => (
  <path transform={`translate(${x} ${y}) scale(${s})`} d="M0 6 C-3 -1 -12 -1 -12 6 C-12 12 -4 16 0 20 C4 16 12 12 12 6 C12 -1 3 -1 0 6 Z" fill={fill} stroke="none" />
);
const Spark: React.FC<{ x: number; y: number; s: number; fill: string; r?: number }> = ({ x, y, s, fill, r = 0 }) => (
  <path transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`} d="M0 -10 L2.4 -2.4 L10 0 L2.4 2.4 L0 10 L-2.4 2.4 L-10 0 L-2.4 -2.4 Z" fill={fill} stroke="none" />
);
// cada ícone recebe `p` = segundos desde que entrou, para a animação própria dele
const IconTalk: React.FC<{ p: number; c: string }> = ({ p, c }) => (
  <SV s={100} c={c}>
    <path d="M20 20 H80 A10 10 0 0 1 90 30 V60 A10 10 0 0 1 80 70 H46 L28 84 V70 H20 A10 10 0 0 1 10 60 V30 A10 10 0 0 1 20 20 Z" />
    {[0, 1, 2].map((i) => (
      <circle key={i} cx={34 + i * 16} cy={45 - Math.max(0, Math.sin((p * 5 - i * 0.7) % (Math.PI * 2))) * 5} r={4.5} fill={c} stroke="none" />
    ))}
  </SV>
);
const IconTarget: React.FC<{ p: number; c: string; bg: string }> = ({ p, c, bg }) => {
  const fly = interpolate(p, [0.15, 0.5], [1, 0], { ...cl, easing: Easing.in(Easing.cubic) });
  const shake = p > 0.5 && p < 0.9 ? Math.sin(p * 70) * 2.4 * (0.9 - p) * 2.5 : 0;
  return (
    <SV s={100} c={c}>
      <circle cx={46} cy={54} r={38} />
      <circle cx={46} cy={54} r={24} />
      <circle cx={46} cy={54} r={9} fill={c} />
      <g transform={`translate(${fly * 60} ${-fly * 60}) rotate(${shake} 46 54)`}>
        <line x1={46} y1={54} x2={88} y2={12} stroke={bg} strokeWidth={14} />
        <line x1={46} y1={54} x2={88} y2={12} />
        <path d="M78 10 L90 10 L90 22" />
        <path d="M84 4 L96 4 L96 16" />
      </g>
    </SV>
  );
};
const IconPin: React.FC<{ p: number; c: string }> = ({ p, c }) => (
  <SV s={100} c={c}>
    <g transform={`rotate(${(-6 + Math.sin(Math.min(p, 1.2) * 9) * 4 * (1 - Math.min(1, p / 1.2))).toFixed(2)} 50 16)`}>
      <rect x={16} y={18} width={68} height={70} rx={8} />
      <Heart x={50} y={44} s={1.5 * (0.6 + 0.4 * pop(p, 0.25, 0.4))} fill={c} />
    </g>
    <circle cx={50} cy={16} r={8} fill={c} />
  </SV>
);
const IconPhone: React.FC<{ p: number; c: string }> = ({ p, c }) => (
  <SV s={100} c={c}>
    <rect x={30} y={8} width={40} height={84} rx={9} />
    <line x1={44} y1={82} x2={56} y2={82} />
    <Heart x={50} y={36} s={1.1 * (0.5 + 0.5 * pop(p, 0.15, 0.4))} fill={c} />
    {[0, 1, 2].map((i) => {
      const u = ((p - 0.3 - i * 0.35) % 1.1) / 1.1;
      return p > 0.3 + i * 0.35 ? <Heart key={i} x={78 + i * 6} y={60 - u * 50} s={0.55} fill={c} /> : null;
    })}
  </SV>
);
const IconBrand: React.FC<{ p: number; c: string }> = ({ p, c }) => (
  <SV s={100} c={c}>
    <g transform={`rotate(${(Math.sin(p * 2.4) * 6).toFixed(2)} 44 50)`}>
      <path d="M44 10 L66 48 L54 84 H34 L22 48 Z" />
      <line x1={44} y1={10} x2={44} y2={44} />
      <circle cx={44} cy={50} r={6} />
    </g>
    {[0, 1, 2].map((i) => (
      <circle key={i} cx={84} cy={24 + i * 26} r={9 * pop(p, 0.2 + i * 0.15, 0.4)} fill={i === 1 ? c : "none"} />
    ))}
  </SV>
);
const IconCamera: React.FC<{ p: number; c: string }> = ({ p, c }) => {
  const shot = p > 0.55 && p < 0.75 ? 1 : 0;
  return (
    <SV s={100} c={c}>
      <path d="M14 34 A8 8 0 0 1 22 26 H34 L40 16 H60 L66 26 H78 A8 8 0 0 1 86 34 V76 A8 8 0 0 1 78 84 H22 A8 8 0 0 1 14 76 Z" />
      <circle cx={50} cy={55} r={18 - shot * 4} />
      <circle cx={50} cy={55} r={7} fill={c} />
      <circle cx={74} cy={38} r={3} fill={c} />
      {shot ? (
        <g strokeWidth={4}>
          {[0, 1, 2, 3, 4, 5].map((i) => (
            <line key={i} x1={50 + Math.cos(i * 1.047) * 30} y1={55 + Math.sin(i * 1.047) * 30} x2={50 + Math.cos(i * 1.047) * 42} y2={55 + Math.sin(i * 1.047) * 42} />
          ))}
        </g>
      ) : null}
    </SV>
  );
};
const IconVideo: React.FC<{ p: number; c: string }> = ({ p, c }) => (
  <SV s={100} c={c}>
    <rect x={10} y={20} width={80} height={56} rx={10} />
    <path d="M42 36 L62 48 L42 60 Z" fill={c} />
    <line x1={14} y1={88} x2={86} y2={88} strokeOpacity={0.35} />
    <line x1={14} y1={88} x2={14 + 72 * Math.min(1, p / 1.6)} y2={88} />
  </SV>
);
const IconWrite: React.FC<{ p: number; c: string }> = ({ p, c }) => {
  const w = lin(p, 0.15, 1.1);
  return (
    <SV s={100} c={c}>
      <rect x={14} y={10} width={52} height={76} rx={8} />
      {[0, 1, 2, 3].map((i) => {
        const f = Math.min(1, Math.max(0, w * 4 - i));
        return f > 0 ? <line key={i} x1={26} y1={28 + i * 14} x2={26 + f * [28, 22, 28, 14][i]} y2={28 + i * 14} /> : null;
      })}
      <g transform={`translate(${(Math.sin(p * 12) * 3).toFixed(1)} ${(w * 20).toFixed(1)})`}>
        <path d="M86 20 L56 62 L52 76 L64 68 L94 26 Z" />
      </g>
    </SV>
  );
};
const IconMega: React.FC<{ p: number; c: string }> = ({ p, c }) => (
  <SV s={100} c={c}>
    <g transform={`rotate(${(-8 + Math.sin(p * 3) * 3).toFixed(2)} 40 50)`}>
      <path d="M14 40 H30 L66 18 V82 L30 60 H14 Z" />
      <path d="M26 60 L32 82 H42 L38 62" />
    </g>
    {[0, 1, 2].map((i) => {
      const u = ((p * 1.4 + i / 3) % 1);
      return <path key={i} d={`M ${76 + u * 14} ${36 - u * 6} Q ${84 + u * 18} 50 ${76 + u * 14} ${64 + u * 6}`} strokeOpacity={1 - u} />;
    })}
  </SV>
);
const IconSpark: React.FC<{ p: number; c: string }> = ({ p, c }) => (
  <SV s={100} c={c}>
    <Spark x={44} y={54} s={3.6 * pop(p, 0.0, 0.5)} fill={c} r={p * 20} />
    <Spark x={80} y={22} s={1.6 * pop(p, 0.2, 0.4)} fill={c} r={-p * 40} />
    <Spark x={18} y={18} s={1.1 * pop(p, 0.35, 0.4)} fill={c} r={p * 50} />
  </SV>
);
const IconPlan: React.FC<{ p: number; c: string }> = ({ p, c }) => (
  <SV s={100} c={c}>
    <rect x={12} y={18} width={76} height={70} rx={10} />
    <line x1={12} y1={36} x2={88} y2={36} />
    <line x1={32} y1={10} x2={32} y2={24} />
    <line x1={68} y1={10} x2={68} y2={24} />
    {[0, 1, 2].map((i) => {
      const f = k(p, 0.15 + i * 0.25, 0.25);
      return <path key={i} d={`M ${24 + i * 22} 60 l 5 6 l 10 -12`} strokeDasharray="30" strokeDashoffset={30 * (1 - f)} />;
    })}
  </SV>
);
const IconPuzzle: React.FC<{ p: number; c: string }> = ({ p, c }) => {
  const join = k(p, 0.1, 0.5);
  return (
    <SV s={100} c={c}>
      <path transform={`translate(${(-(1 - join) * 16).toFixed(1)} 0)`} d="M14 22 H48 V40 A10 10 0 0 1 48 60 V78 H14 Z" fill={c} fillOpacity={0.25} />
      <path transform={`translate(${((1 - join) * 16).toFixed(1)} 0)`} d="M52 22 H86 V78 H52 V60 A10 10 0 0 0 52 40 Z" />
    </SV>
  );
};
const ICON_TILE = (bg: string, border?: string): React.CSSProperties => ({ width: 380, height: 380, borderRadius: 96, background: bg, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: border ? `inset 0 0 0 4px ${border}` : "0 30px 70px rgba(43,33,27,0.22)" });

// ───────── cena 1: a vitrine que ninguém vê ─────────
const Walker: React.FC<{ x: number; t: number; tone: string; look?: number }> = ({ x, t, tone, look = 1 }) => (
  <div style={{ position: "absolute", left: x, top: 1186, width: 100, height: 236, transform: `translateY(${(Math.abs(Math.sin(t * 9)) * -8).toFixed(1)}px)` }}>
    <div style={{ position: "absolute", left: 18, top: 0, width: 64, height: 64, borderRadius: 32, background: OFF }}>
      {[0, 1].map((i) => (
        <div key={i} style={{ position: "absolute", left: 22 + i * 16 + look * 9, top: 26, width: 8, height: 10, borderRadius: 4, background: DEEP }} />
      ))}
    </div>
    <div style={{ position: "absolute", left: 6, top: 74, width: 88, height: 162, borderRadius: "44px 44px 16px 16px", background: tone }} />
  </div>
);
const Store: React.FC<{ t: number; on: number; valor: number; at: number }> = ({ t, on, valor, at }) => {
  const glow = on;
  return (
    <>
      {/* chão */}
      <div style={{ position: "absolute", left: 60, right: 60, top: 1420, height: 14, borderRadius: 8, background: CARAMELO, transform: `scaleX(${k(t, at, 0.5)})` }} />
      {/* prédio */}
      <div style={{ position: "absolute", left: 250, top: 900, width: 580, height: 520, borderRadius: "22px 22px 0 0", background: AREIA, transform: `translateY(${((1 - pop(t, at + 0.05, 0.5)) * 520).toFixed(1)}px)`, opacity: k(t, at + 0.05, 0.1) }}>
        {/* vitrine */}
        <div style={{ position: "absolute", left: 40, top: 130, width: 280, height: 270, borderRadius: 18, background: interpolate(glow, [0, 1], [0, 1]) > 0.5 ? "#FFF6E4" : "#7A6858", boxShadow: `inset 0 0 0 10px ${CAFE}, 0 0 ${(70 * glow).toFixed(0)}px rgba(255,236,200,${(0.55 * glow).toFixed(2)})`, transition: "none" }}>
          <div style={{ position: "absolute", inset: 10, borderRadius: 10, background: `rgba(255,246,228,${glow.toFixed(2)})` }} />
          {/* o produto de valor na vitrine */}
          <svg width={150} height={150} viewBox="-50 -50 100 100" style={{ position: "absolute", left: 65, top: 40, transform: `scale(${pop(t, at + 0.75, 0.5)})` }}>
            <path d="M-30 -12 L-16 -30 H16 L30 -12 L0 32 Z" fill={valor > 0.5 ? CARAMELO : "#9E8F82"} stroke={CAFE} strokeWidth={5} strokeLinejoin="round" />
            <path d="M-30 -12 H30 M-16 -30 L-6 -12 L0 32 M16 -30 L6 -12" fill="none" stroke={CAFE} strokeWidth={4} strokeLinejoin="round" />
          </svg>
          <div style={{ position: "absolute", left: 40, right: 40, bottom: 34, height: 26, borderRadius: 8, background: CAFE }} />
        </div>
        {/* porta */}
        <div style={{ position: "absolute", left: 360, top: 170, width: 180, height: 350, borderRadius: "18px 18px 0 0", background: CAFE }}>
          <div style={{ position: "absolute", left: 140, top: 180, width: 16, height: 16, borderRadius: 8, background: AREIA }} />
          <div style={{ position: "absolute", left: 24, top: 26, width: 132, height: 120, borderRadius: 12, background: glow > 0.5 ? "#FFF6E4" : "#7A6858", opacity: 0.9 }} />
        </div>
      </div>
      {/* toldo */}
      <div style={{ position: "absolute", left: 226, top: 880, width: 628, display: "flex", transformOrigin: "50% 0", transform: `scaleY(${pop(t, at + 0.3, 0.45)})` }}>
        {Array.from({ length: 7 }, (_, i) => (
          <div key={i} style={{ flex: 1, height: 120, background: i % 2 ? OFF : CARAMELO, borderRadius: "0 0 46px 46px" }} />
        ))}
      </div>
      {/* placa */}
      <div style={{ position: "absolute", left: 340, top: 770, width: 400, height: 96, borderRadius: 22, background: CAFE, display: "flex", alignItems: "center", justifyContent: "center", gap: 18, transform: `translateY(${((1 - pop(t, at + 0.5, 0.45)) * -260).toFixed(1)}px)` }}>
        {[0, 1, 2].map((i) => (
          <svg key={i} width={44} height={44} viewBox="-12 -12 24 24">
            <Spark x={0} y={0} s={1} fill={glow > 0.5 ? AREIA : "#7A6858"} r={i * 15} />
          </svg>
        ))}
      </div>
    </>
  );
};
const Plant: React.FC<{ t: number; at: number; droop: number; x?: number }> = ({ t, at, droop, x = 860 }) => {
  const grow = k(t, at, 0.6);
