// ───────── cena 4: o diferencial ─────────
const Chart: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const draw = io(t, at + 0.2, 1.3);
  const pts = [[0, 300], [150, 240], [300, 255], [450, 140], [600, 40]];
  const len = pts.length - 1;
  const n = draw * len;
  const shown = pts.slice(0, Math.floor(n) + 1).map((p) => p.join(","));
  if (n < len) {
    const i = Math.floor(n);
    const f = n - i;
    shown.push(`${pts[i][0] + (pts[i + 1][0] - pts[i][0]) * f},${pts[i][1] + (pts[i + 1][1] - pts[i][1]) * f}`);
  }
  const tip = shown[shown.length - 1].split(",").map(Number);
  const ang = n < len ? Math.atan2(pts[Math.min(len, Math.floor(n) + 1)][1] - pts[Math.floor(n)][1], pts[Math.min(len, Math.floor(n) + 1)][0] - pts[Math.floor(n)][0]) : Math.atan2(-100, 150);
  return (
    <svg width={760} height={520} viewBox="-80 -80 760 520" style={{ overflow: "visible" }}>
      {[0, 1, 2, 3].map((i) => (
        <rect key={i} x={40 + i * 150} y={360 - [90, 150, 220, 320][i] * pop(t, at + 0.1 + i * 0.22, 0.5)} width={90} height={[90, 150, 220, 320][i] * pop(t, at + 0.1 + i * 0.22, 0.5)} rx={16} fill={i === 3 ? CARAMELO : "#4B3428"} />
      ))}
      <line x1={-20} y1={362} x2={680} y2={362} stroke={CARAMELO} strokeWidth={8} strokeLinecap="round" />
      <polyline points={shown.join(" ")} fill="none" stroke={AREIA} strokeWidth={14} strokeLinecap="round" strokeLinejoin="round" />
      {draw > 0 ? <path d="M -26 -22 L 10 0 L -26 22" fill="none" stroke={AREIA} strokeWidth={14} strokeLinecap="round" strokeLinejoin="round" transform={`translate(${tip[0]} ${tip[1]}) rotate(${(ang * 180) / Math.PI})`} /> : null}
    </svg>
  );
};
