// ───────── transições (cada troca é diferente da anterior) ─────────
// barras que sobem como um gráfico e cobrem a tela, depois saem por cima
const BarsUp: React.FC<{ t: number; at: number; colors: string[] }> = ({ t, at, colors }) => {
  if (t < at - 0.45 || t > at + 0.5) return null;
  return (
    <AbsoluteFill>
      {Array.from({ length: 6 }, (_, i) => {
        const d = i * 0.045;
        const up = io(t, at - 0.42 + d, 0.3);
        const off = io(t, at + 0.02 + d, 0.3);
        return <div key={i} style={{ position: "absolute", left: i * 180, width: 182, top: 0, height: 1920, background: colors[i % colors.length], transformOrigin: off > 0 ? "50% 0" : "50% 100%", transform: `scaleY(${(off > 0 ? 1 - off : up).toFixed(4)})` }} />;
      })}
    </AbsoluteFill>
  );
};
// faixas que atravessam da esquerda para a direita
const BarsSide: React.FC<{ t: number; at: number; colors: string[] }> = ({ t, at, colors }) => {
  if (t < at - 0.45 || t > at + 0.5) return null;
  return (
    <AbsoluteFill>
      {Array.from({ length: 8 }, (_, i) => {
        const d = i * 0.035;
        const inn = io(t, at - 0.42 + d, 0.3);
        const off = io(t, at + 0.02 + d, 0.3);
        return <div key={i} style={{ position: "absolute", top: i * 240, height: 242, left: 0, width: 1080, background: colors[i % colors.length], transformOrigin: off > 0 ? "100% 50%" : "0 50%", transform: `scaleX(${(off > 0 ? 1 - off : inn).toFixed(4)})` }} />;
      })}
    </AbsoluteFill>
  );
};
// círculo que abre a partir de um ponto
const Iris: React.FC<{ t: number; at: number; color: string; x?: number; y?: number }> = ({ t, at, color, x = 540, y = 960 }) => {
  if (t < at - 0.4 || t > at + 0.02) return null;
  const r = io(t, at - 0.4, 0.4) * 2300;
  return <div style={{ position: "absolute", left: x - r, top: y - r, width: r * 2, height: r * 2, borderRadius: "50%", background: color }} />;
};

const SCENES: { C: React.FC<{ t: number }>; at: number; bg: string }[] = [
  { C: S1, at: 0, bg: DEEP },
  { C: S2, at: 7.25, bg: OFF },
  { C: S3a, at: 14.4, bg: CAFE },
  { C: S3b, at: 17.05, bg: AREIA },
  { C: S3c, at: 20.9, bg: OFF },
  { C: S4, at: 27.55, bg: DEEP },
  { C: S5, at: 32.55, bg: CAFE },
];
export const Growth: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / GR_FPS;
  // 3a → 3b desliza (empurra para a esquerda); 4 → 5 atravessa o gráfico (zoom)
  const slide = io(t, 17.05 - 0.3, 0.45);
  const zoom = io(t, 32.55 - 0.35, 0.5);
  return (
    <AbsoluteFill style={{ background: DEEP, fontFamily: FONT }}>
      {SCENES.map((s, i) => {
        const next = SCENES[i + 1];
        const keepOut = i === 2 ? 0.2 : i === 5 ? 0.2 : 0;
        const earlyIn = i === 3 ? 0.3 : i === 6 ? 0.35 : 0;
        if (t < s.at - earlyIn || (next && t >= next.at + keepOut)) return null;
        let style: React.CSSProperties = {};
        if (i === 2) style = { transform: `translateX(${(-slide * 1080).toFixed(1)}px)` };
        if (i === 3) style = { transform: `translateX(${((1 - slide) * 1080).toFixed(1)}px)` };
        if (i === 5) style = { transform: `scale(${(1 + zoom * 2.4).toFixed(4)})`, transformOrigin: "840px 880px", opacity: 1 - io(t, 32.55 - 0.1, 0.3) };
        if (i === 6) style = { opacity: io(t, 32.55 - 0.35, 0.4), transform: `scale(${(1.15 - 0.15 * io(t, 32.55 - 0.35, 0.6)).toFixed(4)})` };
        return (
          <AbsoluteFill key={i} style={{ background: s.bg, zIndex: i === 6 ? 0 : 1, ...style }}>
            <s.C t={t} />
          </AbsoluteFill>
        );
      })}
      <BarsUp t={t} at={7.25} colors={[CARAMELO, CAFE]} />
      <Iris t={t} at={14.4} color={CAFE} y={1000} />
      <BarsSide t={t} at={20.9} colors={[CAFE, CARAMELO]} />
      <Iris t={t} at={27.55} color={DEEP} x={540} y={1900} />
    </AbsoluteFill>
  );
};

